# sound effects for ep30 — cues(B, bs, be, mk, cue, end_start); times on the story timeline (cover offset is added for you)
def cues(B, bs, be, mk, cue, end_start):
    a = bs(0); cue(a + .05, 'whoosh'); cue(a + .3, 'sparkle', .3); z = mk(0, 'zing', .35); cue(z - .3, 'slide_down', .3); cue(z, 'boing', .45); cue(mk(0, 'ask', .65), 'pop', .35)
    a = bs(1); cue(a, 'whoosh'); cue(mk(1, 'drill', .1), 'drill', .45); cue(mk(1, 'nerve', .35) - .2, 'pop', .4); c = mk(1, 'cold', .7); cue(c, 'slide_down', .3); z = mk(1, 'zing', .82); cue(z, 'click', .45); cue(z + .05, 'boing', .5)
    a = bs(2); cue(a, 'whoosh'); p = mk(2, 'paste', .05); cue(p, 'slide_up', .3); cue(p + .5, 'scrub', .4); cue(p + 1.3, 'scrub', .35); cue(mk(2, 'soft', .3) + .3, 'scrub', .35)
    cue(mk(2, 'avoid', .45), 'pop', .35); cue(mk(2, 'weeks', .7), 'chime', .4)
    a = bs(3); cue(a, 'whoosh'); cue(a + .1, 'pop', .3); o = mk(3, 'ouch', .25); cue(o, 'thud', .5); cue(o + .05, 'sad', .3); cue(o + 1.6, 'thud', .3); cue(mk(3, 'high', .6), 'ding', .35)
    a = bs(4); cue(a, 'whoosh'); p = mk(4, 'paper', .15); cue(p - .3, 'slide_up', .3); cue(p + .5, 'click', .4); cue(mk(4, 'trim', .45), 'drill', .4); t = mk(4, 'term', .75); cue(t, 'click', .4); cue(t + .1, 'sparkle', .4)
    a = bs(5); cue(a, 'whoosh'); cue(mk(5, 'deep', .1), 'slide_down', .35); cue(mk(5, 'linger', .3), 'tick', .35); th = mk(5, 'throb', .65)
    for k in range(3): cue(th + k * .52, 'thud', .45)
    a = bs(6); cue(a, 'whoosh'); cue(mk(6, 'xray', .3), 'ding', .45); cue(mk(6, 'rc', .75), 'chime', .4)
    a = bs(7); cue(a, 'slide_up', .35); cue(mk(7, 'ok', .1) + .2, 'boing', .35); cue(mk(7, 'ok', .1) + .8, 'ding', .35); cue(mk(7, 'bad', .45), 'thud', .45); cue(mk(7, 'go', .75), 'pop', .4)
    a = bs(8); cue(a, 'whoosh'); cue(mk(8, 'no', .45), 'boing', .45); cue(mk(8, 'adapt', .65), 'sparkle', .4)
    cue(bs(9), 'fanfare'); ch = mk(9, 'chew', .35); cue(ch + .2, 'click', .3); cue(ch + .6, 'click', .3); cue(end_start + .15, 'sparkle')
